sp_widget.client_script:
api.controller = function($location, $http) {

    var c = this;

    c.form = {
        document_type: "",
        document_name: ""
    };

    c.selectedFile = null;
    c.fileName = "";
    c.uploading = false;
    c.successMessage = "";
    c.errorMessage = "";

    // Get Claim Sys ID from URL
    var params = $location.search();

    c.claimSysId = params.sys_id || "";

    // -----------------------------------------
    // File selection
    // -----------------------------------------

    c.fileSelected = function(input) {

        c.errorMessage = "";
        c.selectedFile = null;
        c.fileName = "";

        if (input.files && input.files.length > 0) {

            c.selectedFile = input.files[0];
            c.fileName = input.files[0].name;

        }
    };


    // -----------------------------------------
    // Upload Document
    // -----------------------------------------

    c.uploadDocument = function() {

        c.successMessage = "";
        c.errorMessage = "";

        // Check Claim
        if (!c.claimSysId) {

            c.errorMessage =
                "Claim information is missing.";

            return;
        }

        // Check Document Type
        if (!c.form.document_type) {

            c.errorMessage =
                "Please select a document type.";

            return;
        }

        // Check Document Name
        if (!c.form.document_name) {

            c.errorMessage =
                "Please enter the document name.";

            return;
        }

        // Check File
        if (!c.selectedFile) {

            c.errorMessage =
                "Please select a file.";

            return;
        }

        c.uploading = true;


        // -----------------------------------------
        // Create Claim Document record
        // -----------------------------------------

        c.server.get({

            action: "create_document",

            claim_sys_id: c.claimSysId,

            document_type: c.form.document_type,

            document_name: c.form.document_name

        }).then(function(response) {

            if (!response.data.success) {

                c.uploading = false;

                c.errorMessage =
                    response.data.message ||
                    "Unable to create document record.";

                return;
            }


            // Get Document Sys ID
            var documentSysId =
                response.data.document_sys_id;


            // -----------------------------------------
            // Prepare attachment
            // -----------------------------------------

            var formData = new FormData();

            formData.append(
                "file",
                c.selectedFile
            );


            var uploadUrl =
                "/api/now/attachment/file" +
                "?table_name=x_snc_insurance_0_claim_document" +
                "&table_sys_id=" +
                encodeURIComponent(documentSysId) +
                "&file_name=" +
                encodeURIComponent(c.selectedFile.name);


            // -----------------------------------------
            // Upload attachment
            // -----------------------------------------

            $http({

                method: "POST",

                url: uploadUrl,

                data: formData,

                transformRequest: angular.identity,

                headers: {
                    "Content-Type": undefined,
                    "Accept": "application/json",
                    "X-UserToken": window.g_ck
                }

            }).then(function(response) {

                c.uploading = false;

                /*
                 * Upload completed successfully.
                 */

                c.successMessage =
                    "Document uploaded successfully.";


                /*
                 * Move directly to Document Status.
                 *
                 * Pass the exact Document Sys ID.
                 */

                var statusUrl =
                    "?id=document_status" +
                    "&document_sys_id=" +
                    encodeURIComponent(documentSysId);


                window.location.href = statusUrl;


            }, function(error) {

                c.uploading = false;

                c.errorMessage =
                    "Document record was created, but file upload failed.";

            });


        }, function(error) {

            c.uploading = false;

            c.errorMessage =
                "Unable to create document record.";

        });

    };


    // -----------------------------------------
    // Back to Home
    // -----------------------------------------

    c.goHome = function() {

        window.location.href =
            "?id=claim_home";

    };

};

sp_widget.css:
.document-container {
    max-width: 900px;
    margin: 40px auto;
    padding: 20px;
    font-family: Arial, sans-serif;
}

.document-header {
    background: linear-gradient(135deg, #0d6efd, #1554a5);
    color: white;
    padding: 30px;
    border-radius: 12px 12px 0 0;
    display: flex;
    align-items: center;
    gap: 18px;
}

.document-icon {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    background: rgba(255,255,255,0.18);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 30px;
}

.document-header h1 {
    margin: 0 0 8px;
    font-size: 27px;
}

.document-header p {
    margin: 0;
    opacity: 0.9;
}

.document-card {
    background: white;
    padding: 35px;
    border: 1px solid #e1e5eb;
    border-radius: 0 0 12px 12px;
    box-shadow: 0 4px 15px rgba(0,0,0,0.08);
}

.document-card h2 {
    color: #183b67;
    margin-top: 0;
}

.subtitle {
    color: #6c757d;
    margin-bottom: 25px;
}

.form-group {
    margin-bottom: 22px;
}

.form-group label {
    display: block;
    font-weight: 600;
    color: #34495e;
    margin-bottom: 8px;
}

.form-group label span {
    color: #dc3545;
}

.form-control {
    width: 100%;
    min-height: 44px;
    padding: 10px 12px;
    border: 1px solid #ccd4dd;
    border-radius: 6px;
    box-sizing: border-box;
}

.file-input {
    width: 100%;
    padding: 12px;
    border: 1px dashed #9db5cf;
    border-radius: 6px;
    background: #f8fbff;
    box-sizing: border-box;
}

.form-group small {
    display: block;
    margin-top: 7px;
    color: #6c757d;
}

.selected-file {
    background: #eef6ff;
    padding: 12px;
    border-radius: 6px;
    margin-bottom: 20px;
    color: #24527a;
}

.info-box {
    background: #eef6ff;
    border-left: 4px solid #0d6efd;
    padding: 15px;
    margin: 20px 0;
    color: #36516c;
}

.form-actions {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    margin-top: 25px;
}

.back-btn,
.upload-btn {
    padding: 12px 24px;
    border-radius: 6px;
    font-weight: 600;
    cursor: pointer;
}

.back-btn {
    background: white;
    border: 1px solid #adb5bd;
    color: #495057;
}

.upload-btn {
    background: #0d6efd;
    border: none;
    color: white;
}

.upload-btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.success-message {
    background: #e8f7ee;
    color: #18733c;
    border: 1px solid #b8e0c7;
    padding: 13px;
    border-radius: 6px;
    margin-top: 15px;
}

.error-message {
    background: #fdecec;
    color: #a52834;
    border: 1px solid #f1b7bc;
    padding: 13px;
    border-radius: 6px;
    margin-top: 15px;
}

@media (max-width: 700px) {

    .document-container {
        padding: 10px;
    }

    .document-card {
        padding: 22px;
    }

    .form-actions {
        flex-direction: column;
    }

    .back-btn,
    .upload-btn {
        width: 100%;
    }
}

sp_widget.script:
(function() {

    data.success = false;
    data.message = "";
    data.document_sys_id = "";

    if (!input || input.action != "create_document") {
        return;
    }

    try {

        var claimSysId =
            String(input.claim_sys_id || "");

        var documentType =
            String(input.document_type || "");

        var documentName =
            String(input.document_name || "");


        if (!claimSysId) {

            data.message =
                "Claim information is missing.";

            return;
        }


        if (!documentType) {

            data.message =
                "Document type is required.";

            return;
        }


        if (!documentName) {

            data.message =
                "Document name is required.";

            return;
        }


        // Find Claim
        var claim =
            new GlideRecord(
                "x_snc_insurance_0_claim"
            );

        if (!claim.get(claimSysId)) {

            data.message =
                "Claim record was not found.";

            return;
        }


        var userEmail = gs.getUser().getEmail();
        var ph = new GlideRecord("x_snc_insurance_0_policyholder");
        ph.addQuery("email", userEmail);
        ph.setLimit(1);
        ph.query();
        var phSysId = ph.next() ? ph.getUniqueValue() : "invalid";
        if (claim.getValue("policyholder") != phSysId) {

            data.message = "Claim record was not found or access denied.";
            return;
        }


        // Create Claim Document
        var document =
            new GlideRecord(
                "x_snc_insurance_0_claim_document"
            );

        document.initialize();


        // Link document to Claim
        document.setValue(
            "claim",
            claimSysId
        );


        // Document Type
        document.setValue(
            "document_type",
            documentType
        );


        // Document Name
        document.setValue(
            "document_name",
            documentName
        );


        // Initial validation status
        document.setValue(
            "document_validation_status",
            "pending"
        );


        // Insert
        var documentSysId =
            document.insert();


        if (!documentSysId) {

            data.message =
                "Unable to create document record.";

            return;
        }


        data.success = true;

        data.document_sys_id =
            documentSysId;

        data.message =
            "Document record created successfully.";


    } catch (e) {

        data.success = false;

        data.message =
            "Error creating document: " +
            e.message;

    }

})();
